":"Resolve one bounded exact-head review and publish only with correct base and Closes #5829 linkage.","acceptance_ids":["AC-1","AC-2","AC-3","AC-4","AC-5","AC-6","AC-7","AC-8","AC-9"],"status":"pending"}],"validation_lanes":[{"lane":"capability_envelope-runtime-v3","proof_role":"Run the exact Runtime v3 integration target and fail when the selected target contains no tests.","acceptance_ids":["AC-1","AC-2","AC-3","AC-4","AC-5","AC-6","AC-7","AC-8","AC-9"],"deterministic":true,"resource_profile":"medium","budget_seconds":600,"budget_tokens":4000,"argv":["cargo","nextest","run","--manifest-path","adl-runtime-kernel/Cargo.toml","--test","capability_envelope","--no-tests=fail","--status-level","all"],"parallel_group":"5829-core","defer_reason":null},{"lane":"capability_envelope-native-platform-receipts","proof_role":"Require passed native macOS and Linux receipts with a nonzero test count and identical fixture digest.","acceptance_ids":["AC-4","AC-9"],"deterministic":true,"resource_profile":"small","budget_seconds":30,"budget_tokens":1000,"argv":["ruby","-rjson","-e","receipts=ARGV.map{|p| JSON.parse(File.read(p))};
